  if (role === 'byproduct') return CUSTOM_ALERTS[nm]?.max || BAR_MAX_FALLBACKS[nm] || CUSTOM_ALERTS[nm]?.red || 15000;
  return maxStock(item) || BAR_MAX_FALLBACKS[nm] || 1;
